1	import { useState, useMemo } from "react";
2	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
3	import { Link, useLocation } from "wouter";
4	import { useUser } from "@clerk/react";
5	import { SafeShow as Show } from "@/lib/safeAuth";
6	import { Layout } from "@/components/layout";
7	import { Button } from "@/components/ui/button";
8	import { Badge } from "@/components/ui/badge";
9	import { Input } from "@/components/ui/input";
10	import { Label } from "@/components/ui/label";
11	import { Textarea } from "@/components/ui/textarea";
12	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
13	import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
14	import { Checkbox } from "@/components/ui/checkbox";
15	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
16	import { Switch } from "@/components/ui/switch";
17	import { Skeleton } from "@/components/ui/skeleton";
18	import { SportPill, SPORT_LABELS } from "@/components/sport-icon";
19	import { useToast } from "@/hooks/use-toast";
20	import { customFetch } from "@workspace/api-client-react";
21	import {
22	  Calendar, Clock, MapPin, Plus, Trophy, Lock, Swords,
23	  Globe, Zap, Star, Euro, UserCheck, ChevronDown, Crown, History,
24	} from "lucide-react";
25	
26	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
27	const API = `${BASE}/api`;
28	
29	const SPORTS = ["tennis", "basketball", "padel", "football", "badminton", "squash", "table-tennis", "volleyball", "hockey", "futsal", "floorball", "beach-volleyball", "golf", "bowling", "pickleball"];
30	
31	const SKILL_LABELS: Record<string, string> = {
32	  any: "Bet koks", beginner: "Pradedantysis", intermediate: "Vidutinis", advanced: "Pažengęs",
33	};
34	
35	type FeedKind = "booked" | "casual";
36	
37	interface FeedItem {
38	  kind: FeedKind;
39	  gameId: number;
40	  sport: string;
41	  matchType: string;
42	  visibility: string;
43	  creatorName: string;
44	  creatorUserId: string;
45	  description: string | null;
46	  datetime: string;
47	  minSkillLevel: number | null;
48	  maxSkillLevel: number | null;
49	  bookingId: number | null;
50	  token: string | null;
51	  courtName: string | null;
52	  courtId: number | null;
53	  facilityName: string | null;
54	  facilityCity: string | null;
55	  courtImageUrl: string | null;
56	  date: string | null;
57	  startTime: string | null;
58	  endTime: string | null;
59	  pricePerSlot: number | null;
60	  totalSlots: number | null;
61	  paidSlots: number | null;
62	  slotsLeft: number;
63	  city: string | null;
64	  placeName: string | null;
65	  skillLevel: string | null;
66	  durationMinutes: number | null;
67	  joinedCount: number | null;
68	  playersNeeded: number | null;
69	  isPrivate: boolean;
70	  creatorElo: number | null;
71	  createdAt: string;
72	}
73	
74	function formatDate(dateStr: string): string {
75	  const d = new Date(dateStr + (dateStr.length === 10 ? "T12:00:00" : ""));
76	  return d.toLocaleDateString("lt-LT", { weekday: "short", month: "short", day: "numeric" });
77	}
78	
79	function formatDateTime(iso: string) {
80	  const d = new Date(iso);
81	  return d.toLocaleString("lt-LT", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
82	}
83	
84	function SkillBadge({ min, max, level }: { min?: number | null; max?: number | null; level?: string | null }) {
85	  if (level && level !== "any") {
86	    return (
87	      <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-400/20">
88	        <Star className="w-3 h-3" />{SKILL_LABELS[level] ?? level}
89	      </span>
90	    );
91	  }
92	  if (min == null && max == null) return null;
93	  const label = min != null && max != null
94	    ? `${min.toFixed(1)}–${max.toFixed(1)}`
95	    : min != null ? `≥${min.toFixed(1)}`
96	    : `≤${max!.toFixed(1)}`;
97	  return (
98	    <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-400/20">
99	      <Star className="w-3 h-3" />{label}
100	    </span>
101	  );
102	}
103	
104	function SlotDots({ filled, total, full }: { filled: number; total: number; full: boolean }) {
105	  const visible = Math.min(total, 8);
106	  const filledDots = full ? visible : Math.min(Math.round((filled / Math.max(total, 1)) * visible), visible);
107	  return (
108	    <div className="flex items-center gap-[3px]">
109	      {Array.from({ length: visible }).map((_, i) => (
110	        <div
111	          key={i}
112	          className={`w-2 h-2 rounded-full transition-colors ${
113	            full
114	              ? "bg-emerald-500"
115	              : i < filledDots
116	              ? "bg-primary"
117	              : "bg-muted-foreground/20 border border-muted-foreground/20"
118	          }`}
119	        />
120	      ))}
121	      {total > 8 && (
122	        <span className="text-[10px] text-muted-foreground ml-0.5">{filled}/{total}</span>
123	      )}
124	    </div>
125	  );
126	}
127	
128	function MatchCard({ m, isOwn }: { m: FeedItem; isOwn?: boolean }) {
129	  const isCasual = m.kind === "casual";
130	  const isRated = m.matchType === "rated";
131	  const full = m.slotsLeft === 0;
132	
133	  const joined = isCasual ? (m.joinedCount ?? 0) : (m.paidSlots ?? 0);
134	  const total = isCasual ? (m.playersNeeded ?? 2) : (m.totalSlots ?? 1);
135	
136	  // Left border accent
137	  const accentClass = isRated
138	    ? "border-l-purple-500"
139	    : isCasual
140	    ? "border-l-emerald-500"
141	    : "border-l-primary";
142	
143	  // Date/time strings
144	  let dateLabel: string | null = null;
145	  let timeLabel: string | null = null;
146	  let locationLabel: string | null = null;
147	
148	  if (isCasual) {
149	    const d = new Date(m.datetime);
150	    dateLabel = d.toLocaleDateString("lt-LT", { weekday: "short", month: "2-digit", day: "2-digit" });
151	    const start = d.toLocaleTimeString("lt-LT", { hour: "2-digit", minute: "2-digit" });
152	    if (m.durationMinutes) {
153	      const end = new Date(d.getTime() + m.durationMinutes * 60_000)
154	        .toLocaleTimeString("lt-LT", { hour: "2-digit", minute: "2-digit" });
155	      timeLabel = `${start} – ${end} (${m.durationMinutes} min)`;
156	    } else {
157	      timeLabel = start;
158	    }
159	    locationLabel = [m.city, m.placeName].filter(Boolean).join(", ");
160	  } else {
161	    if (m.date) {
162	      const d = new Date(m.date + "T12:00:00");
163	      dateLabel = d.toLocaleDateString("lt-LT", { weekday: "short", month: "2-digit", day: "2-digit" });
164	    }
165	    if (m.startTime && m.endTime) timeLabel = `${m.startTime} – ${m.endTime}`;
166	    locationLabel = [m.facilityCity, m.facilityName].filter(Boolean).join(", ");
167	  }
168	
169	  return (
170	    <Link href={`/matches/${m.gameId}`}>
171	      <div className={`group relative flex flex-col rounded-xl border border-border border-l-4 ${accentClass} bg-card hover:shadow-lg hover:bg-accent/30 transition-all cursor-pointer overflow-hidden ${full ? "opacity-70" : ""} ${isOwn ? "ring-1 ring-amber-400/40" : ""}`}>
172	
173	        {/* "Mano" ribbon */}
174	        {isOwn && (
175	          <div className="absolute top-0 right-0 z-10 overflow-hidden w-14 h-14 pointer-events-none">
176	            <div className="absolute top-3 -right-4 rotate-45 bg-amber-500 text-white text-[8px] font-black tracking-widest px-5 py-px shadow">
177	              MANO
178	            </div>
179	          </div>
180	        )}
181	
182	        <div className="p-4 flex flex-col gap-3 flex-1">
183	
184	          {/* ── Row 1: badges ── */}
185	          <div className="flex items-center gap-1.5 flex-wrap pr-8">
186	            <SportPill sport={m.sport} variant="subtle" size="sm" />
187	            {isRated && (
188	              <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-purple-500/15 text-purple-400 border border-purple-400/20">
189	                <Swords className="w-3 h-3" />Reitinginis
190	              </span>
191	            )}
192	            {isCasual && (
193	              <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-400/20">
194	                Nemokama
195	              </span>
196	            )}
197	            <SkillBadge min={m.minSkillLevel} max={m.maxSkillLevel} level={m.skillLevel} />
198	          </div>
199	
200	          {/* ── Row 2: main content ── */}
201	          {isCasual ? (
202	            <div className="flex items-start justify-between gap-2">
203	              <div className="min-w-0 flex-1">
204	                <p className="font-bold text-base leading-snug truncate group-hover:text-primary transition-colors">
205	                  {m.creatorName}
206	                </p>
207	                {m.creatorElo != null && (
208	                  <p className="text-[11px] text-amber-600 dark:text-amber-400 font-semibold">ELO {m.creatorElo}</p>
209	                )}
210	                {m.description && (
211	                  <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{m.description}</p>
212	                )}
213	              </div>
214	            </div>
215	          ) : (
216	            <div className="flex items-start justify-between gap-2">
217	              <div className="min-w-0 flex-1">
218	                <p className="font-bold text-base leading-snug truncate group-hover:text-primary transition-colors">
219	                  {m.facilityName || m.courtName}
220	                </p>
221	                {m.facilityName && m.courtName && (
222	                  <p className="text-xs text-muted-foreground truncate">{m.courtName}</p>
223	                )}
224	                {m.description && (
225	                  <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{m.description}</p>
226	                )}
227	              </div>
228	              {m.pricePerSlot != null && (
229	                <div className="shrink-0 text-right">
230	                  <p className="text-xl font-extrabold text-primary leading-none">
231	                    {m.pricePerSlot.toFixed(2)}<span className="text-sm font-semibold"> €</span>
232	                  </p>
233	                  <p className="text-[10px] text-muted-foreground">/ žaid.</p>
234	                </div>
235	              )}
236	            </div>
237	          )}
238	
239	          {/* ── Row 3: metadata ── */}
240	          <div className="space-y-1 text-xs text-muted-foreground">
241	            {dateLabel && (
242	              <div className="flex items-center gap-1.5">
243	                <Calendar className="w-3 h-3 shrink-0" />
244	                <span>{dateLabel}</span>
245	              </div>
246	            )}
247	            {timeLabel && (
248	              <div className="flex items-center gap-1.5">
249	                <Clock className="w-3 h-3 shrink-0" />
250	                <span>{timeLabel}</span>
251	              </div>
252	            )}
253	            {locationLabel && (
254	              <div className="flex items-center gap-1.5">
255	                <MapPin className="w-3 h-3 shrink-0" />
256	                <span className="truncate">{locationLabel}</span>
257	              </div>
258	            )}
259	          </div>
260	
261	          {/* ── Footer ── */}
262	          <div className="flex items-center justify-between pt-2 border-t border-border/60 gap-2 mt-auto">
263	            {/* Creator (booked only — casual shows creator as heading) */}
264	            {!isCasual && (
265	              <div className="flex items-center gap-1.5 min-w-0">
266	                <UserCheck className="w-3 h-3 shrink-0 text-muted-foreground" />
267	                <span className="text-xs text-muted-foreground truncate">{m.creatorName}</span>
268	                {m.creatorElo != null && (
269	                  <span className="text-[10px] font-bold text-amber-600 dark:text-amber-400 shrink-0">{m.creatorElo}</span>
270	                )}
271	              </div>
272	            )}
273	            {isCasual && <div />}
274	
275	            {/* Slot dots + action button */}
276	            <div className="flex items-center gap-2 shrink-0">
277	              <SlotDots filled={joined} total={total} full={full} />
278	              {full ? (
279	                <Button size="sm" disabled className="h-7 px-3 text-xs font-semibold">
280	                  Pilna
281	                </Button>
282	              ) : isOwn ? (
283	                <Button size="sm" variant="outline" className="h-7 px-3 text-xs font-semibold border-amber-400/60 text-amber-600 dark:text-amber-400 hover:bg-amber-500/10">
284	                  Valdyti
285	                </Button>
286	              ) : isCasual ? (
287	                <Button size="sm" className="h-7 px-3 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white border-0">
288	                  Prisijungti
289	                </Button>
290	              ) : m.token ? (
291	                <div onClick={e => e.stopPropagation()}>
292	                  <Link href={`/join/${m.token}`}>
293	                    <Button size="sm" className="h-7 px-3 text-xs font-semibold gap-1">
294	                      <Euro className="w-3 h-3" />Prisijungti
295	                    </Button>
296	                  </Link>
297	                </div>
298	              ) : null}
299	            </div>
300	          </div>
301	
302	        </div>
303	      </div>
304	    </Link>
305	  );
306	}
307	
308	function toMin(t: string): number {
309	  if (!t) return 0;
310	  const [h, m] = t.split(":").map(Number);
311	  return h * 60 + m;
312	}
313	
314	interface CourtListItem { id: number; name: string; sport: string; city: string; pricePerHour: string | number; }
315	interface AvailabilitySlot { startTime: string; endTime: string; available: boolean; price: number; }
316	interface AvailabilityResp { slots: AvailabilitySlot[]; }
317	type Venue = "self" | "korts";
318	
319	function CityMultiSelect({ options, selected, onChange }: { options: string[]; selected: string[]; onChange: (v: string[]) => void }) {
320	  const [open, setOpen] = useState(false);
321	  const toggle = (city: string) =>
322	    onChange(selected.includes(city) ? selected.filter(c => c !== city) : [...selected, city]);
323	  const label = selected.length === 0
324	    ? "Visi miestai"
325	    : selected.length === 1
326	    ? selected[0]
327	    : `${selected.length} miestai`;
328	
329	  return (
330	    <Popover open={open} onOpenChange={setOpen}>
331	      <PopoverTrigger asChild>
332	        <button className="flex h-9 w-full items-center justify-between rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-xs ring-offset-background focus:outline-none focus:ring-1 focus:ring-ring">
333	          <span className={selected.length === 0 ? "text-muted-foreground" : ""}>{label}</span>
334	          <ChevronDown className="h-4 w-4 opacity-50 shrink-0" />
335	        </button>
336	      </PopoverTrigger>
337	      <PopoverContent className="w-52 p-2" align="start">
338	        {options.length === 0 ? (
339	          <p className="text-xs text-muted-foreground px-2 py-1.5">Nėra duomenų</p>
340	        ) : (
341	          <div className="max-h-64 overflow-y-auto space-y-0.5">
342	            {options.map(city => (
343	              <label key={city} className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-accent cursor-pointer text-sm select-none">
344	                <Checkbox checked={selected.includes(city)} onCheckedChange={() => toggle(city)} />
345	                {city}
346	              </label>
347	            ))}
348	          </div>
349	        )}
350	        {selected.length > 0 && (
351	          <div className="border-t mt-1 pt-1">
352	            <button onClick={() => { onChange([]); setOpen(false); }}
353	              className="w-full text-xs text-muted-foreground hover:text-destructive px-2 py-1 text-left transition-colors">
354	              Išvalyti pasirinkimą
355	            </button>
356	          </div>
357	        )}
358	      </PopoverContent>
359	    </Popover>
360	  );
361	}
362	
363	function CreateGameDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (v: boolean) => void }) {
364	  const { user } = useUser();
365	  const { toast } = useToast();
366	  const qc = useQueryClient();
367	  const [, setLocation] = useLocation();
368	
369	  const [venue, setVenue] = useState<Venue>("self");
370	  const [courtId, setCourtId] = useState<number | null>(null);
371	  const [bookingStart, setBookingStart] = useState<string>("");
372	  const [bookingEnd, setBookingEnd] = useState<string>("");
373	
374	  const [form, setForm] = useState({
375	    sport: "tennis",
376	    city: "Vilnius",
377	    placeName: "",
378	    playersNeeded: 4,
379	    skillLevel: "any",
380	    date: new Date(Date.now() + 24 * 3600 * 1000).toISOString().slice(0, 10),
381	    time: "18:00",
382	    durationMinutes: 60,
383	    description: "",
384	    isPrivate: false,
385	    matchType: "casual" as "casual" | "rated",
386	  });
387	
388	  const courtsQ = useQuery<CourtListItem[]>({
389	    queryKey: ["courts-for-game", form.sport, form.city],
390	    queryFn: () => customFetch<CourtListItem[]>(`${API}/courts?sport=${encodeURIComponent(form.sport)}&city=${encodeURIComponent(form.city)}`),
391	    enabled: venue === "korts" && open,
392	  });
393	
394	  const availabilityQ = useQuery<AvailabilityResp>({
395	    queryKey: ["court-availability-for-game", courtId, form.date],
396	    queryFn: () => customFetch<AvailabilityResp>(`${API}/courts/${courtId}/availability?date=${form.date}`),
397	    enabled: venue === "korts" && courtId != null && open,
398	  });
399	
400	  const selectedRangePrice = (() => {
401	    if (venue !== "korts" || !bookingStart || !bookingEnd || !availabilityQ.data) return null;
402	    const startM = toMin(bookingStart), endM = toMin(bookingEnd);
403	    let total = 0;
404	    for (const s of availabilityQ.data.slots) {
405	      const sM = toMin(s.startTime);
406	      if (sM >= startM && sM < endM) total += Number(s.price ?? 0);
407	    }
408	    return total;
409	  })();
410	
411	  const create = useMutation({
412	    mutationFn: async () => {
413	      if (venue === "korts") {
414	        if (!courtId || !bookingStart || !bookingEnd) throw new Error("Pasirinkite aikštę ir laiką");
415	        const successUrl = `${window.location.origin}${BASE}/matches?payment=success`;
416	        const cancelUrl = `${window.location.origin}${BASE}/matches?payment=cancelled`;
417	        const resp = await customFetch<{ checkoutUrl: string; gameId: number; bookingId: number }>(`${API}/games/checkout`, {
418	          method: "POST",
419	          headers: { "Content-Type": "application/json" },
420	          body: JSON.stringify({
421	            creatorName: user?.fullName || user?.firstName || "Žaidėjas",
422	            creatorEmail: user?.emailAddresses[0]?.emailAddress,
423	            sport: form.sport,
424	            city: form.city,
425	            placeName: form.placeName || null,
426	            playersNeeded: form.playersNeeded,
427	            skillLevel: form.skillLevel,
428	            durationMinutes: toMin(bookingEnd) - toMin(bookingStart),
429	            description: form.description || null,
430	            isPrivate: form.isPrivate,
431	            matchType: form.matchType,
432	            courtId,
433	            bookingDate: form.date,
434	            bookingStart,
435	            bookingEnd,
436	            successUrl,
437	            cancelUrl,
438	          }),
439	        });
440	        return { redirectUrl: resp.checkoutUrl } as { redirectUrl: string };
441	      }
442	      const datetime = new Date(`${form.date}T${form.time}:00`).toISOString();
443	      const res = await customFetch<{ id: number }>(`${API}/games`, {
444	        method: "POST",
445	        headers: { "Content-Type": "application/json" },
446	        body: JSON.stringify({
447	          creatorName: user?.fullName || user?.firstName || "Žaidėjas",
448	          creatorEmail: user?.emailAddresses[0]?.emailAddress,
449	          sport: form.sport,
450	          city: form.city,
451	          placeName: form.placeName || null,
452	          playersNeeded: form.playersNeeded,
453	          skillLevel: form.skillLevel,
454	          datetime,
455	          durationMinutes: form.durationMinutes,
456	          description: form.description || null,
457	          isPrivate: form.isPrivate,
458	          matchType: form.matchType,
459	        }),
460	      });
461	      return res;
462	    },
463	    onSuccess: async (result) => {
464	      if ("redirectUrl" in (result as any)) {
465	        window.location.href = (result as { redirectUrl: string }).redirectUrl;
466	        return;
467	      }
468	      await qc.refetchQueries({ queryKey: ["open-matches"] });
469	      toast({ title: "Žaidimas sukurtas!", description: "Galite pasidalinti nuoroda su draugais." });
470	      onOpenChange(false);
471	      setLocation(`/matches/${(result as { id: number }).id}`);
472	    },
473	    onError: (e: any) => {
474	      toast({ title: "Nepavyko sukurti", description: e?.message ?? "Klaida", variant: "destructive" });
475	    },
476	  });
477	
478	  return (
479	    <Dialog open={open} onOpenChange={onOpenChange}>
480	      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
481	        <DialogHeader>
482	          <DialogTitle>Sukurti naują žaidimą</DialogTitle>
483	          <DialogDescription>Raskite partnerių tarp korts.lt bendruomenės.</DialogDescription>
484	        </DialogHeader>
485	        <div className="space-y-4 py-2">
486	          <div className="grid grid-cols-2 gap-2">
487	            <button type="button" onClick={() => setForm(f => ({ ...f, matchType: "casual" }))}
488	              className={`flex flex-col items-center gap-1.5 p-3 rounded-xl border-2 transition-all ${form.matchType === "casual" ? "border-primary bg-primary/10" : "border-border hover:border-border/80"}`}>
489	              <Trophy className="w-5 h-5" />
490	              <span className="text-sm font-semibold">Laisvas</span>
491	              <span className="text-xs text-muted-foreground">ELO nekinta</span>
492	            </button>
493	            <button type="button" onClick={() => setForm(f => ({ ...f, matchType: "rated" }))}
494	              className={`flex flex-col items-center gap-1.5 p-3 rounded-xl border-2 transition-all ${form.matchType === "rated" ? "border-purple-500 bg-purple-500/10" : "border-border hover:border-border/80"}`}>
