530	              {venue === "self" ? (
531	                <Input className="mt-1" placeholder="pvz. Forum Palace aikštelės" value={form.placeName}
532	                  onChange={(e) => setForm(f => ({ ...f, placeName: e.target.value }))} />
533	              ) : (
534	                <p className="text-xs text-muted-foreground mt-2">Pasirinkite Korts.lt aikštę žemiau.</p>
