539	          <div className="grid grid-cols-2 gap-2">
540	            <button type="button" onClick={() => { setVenue("self"); setCourtId(null); }}
541	              className={`flex flex-col items-center gap-1 p-3 rounded-xl border-2 transition-all ${venue === "self" ? "border-primary bg-primary/10" : "border-border hover:border-border/80"}`}>
542	              <MapPin className="w-5 h-5" />
543	              <span className="text-sm font-semibold">Sava vieta</span>
544	              <span className="text-xs text-muted-foreground">Susitarta atskirai</span>
545	            </button>
546	            <button type="button" onClick={() => setVenue("korts")}
547	              className={`flex flex-col items-center gap-1 p-3 rounded-xl border-2 transition-all ${venue === "korts" ? "border-primary bg-primary/10" : "border-border hover:border-border/80"}`}>
548	              <Calendar className="w-5 h-5" />
549	              <span className="text-sm font-semibold">Korts.lt aikštė</span>
550	              <span className="text-xs text-muted-foreground">Apmokėsite dabar</span>
551	            </button>
552	          </div>
553	
554	          {venue === "korts" && (
555	            <div className="space-y-3 rounded-lg border border-primary/40 bg-primary/5 p-3">
556	              <div>
557	                <Label>Aikštė</Label>
558	                {courtsQ.isLoading ? (
559	                  <Skeleton className="h-10 mt-1" />
560	                ) : (courtsQ.data?.length ?? 0) === 0 ? (
561	                  <p className="text-xs text-muted-foreground mt-1">Nėra aikščių pasirinktam sportui ir miestui.</p>
562	                ) : (
563	                  <Select value={courtId ? String(courtId) : ""} onValueChange={(v) => { setCourtId(parseInt(v, 10)); setBookingStart(""); setBookingEnd(""); }}>
564	                    <SelectTrigger className="mt-1"><SelectValue placeholder="Pasirinkite aikštę" /></SelectTrigger>
565	                    <SelectContent className="max-h-72">
566	                      {courtsQ.data!.map(c => (
567	                        <SelectItem key={c.id} value={String(c.id)}>
568	                          {c.name} — €{Number(c.pricePerHour).toFixed(2)}/h
569	                        </SelectItem>
570	                      ))}
571	                    </SelectContent>
572	                  </Select>
573	                )}
574	              </div>
575	              {courtId != null && (
576	                <div className="grid grid-cols-2 gap-3">
577	                  <div>
578	                    <Label>Pradžia</Label>
579	                    {availabilityQ.isLoading ? <Skeleton className="h-10 mt-1" /> : (
580	                      <Select value={bookingStart} onValueChange={(v) => { setBookingStart(v); if (bookingEnd && toMin(bookingEnd) <= toMin(v)) setBookingEnd(""); }}>
581	                        <SelectTrigger className="mt-1"><SelectValue placeholder="--:--" /></SelectTrigger>
582	                        <SelectContent className="max-h-72">
583	                          {(availabilityQ.data?.slots ?? []).filter(s => s.available).map(s => (
584	                            <SelectItem key={s.startTime} value={s.startTime}>{s.startTime}</SelectItem>
585	                          ))}
586	                        </SelectContent>
587	                      </Select>
