591	                    <Label>Pabaiga</Label>
592	                    <Select value={bookingEnd} onValueChange={setBookingEnd} disabled={!bookingStart}>
593	                      <SelectTrigger className="mt-1"><SelectValue placeholder="--:--" /></SelectTrigger>
594	                      <SelectContent className="max-h-72">
595	                        {(availabilityQ.data?.slots ?? []).filter(s => bookingStart && toMin(s.endTime) > toMin(bookingStart)).map(s => (
596	                          <SelectItem key={s.endTime} value={s.endTime}>{s.endTime}</SelectItem>
