604	                <div className="rounded-md bg-background/60 border border-border p-2 text-sm">
605	                  <div className="flex items-center justify-between">
606	                    <span className="text-muted-foreground">Aikštės kaina:</span>
607	                    <span className="font-bold">€{selectedRangePrice.toFixed(2)}</span>
