611	                  </p>
612	                </div>
613	              )}
614	            </div>
615	          )}
616	
617	          {venue === "self" && (
618	            <div className="grid grid-cols-3 gap-3">
619	              <div>
620	                <Label>Data</Label>
621	                <Input type="date" className="mt-1" value={form.date} onChange={(e) => setForm(f => ({ ...f, date: e.target.value }))} />
622	              </div>
623	              <div>
