669	            {create.isPending
670	              ? (venue === "korts" ? "Nukreipiama į Stripe..." : "Kuriama...")
671	              : (venue === "korts"
672	                ? `Apmokėti ir sukurti${selectedRangePrice != null ? ` (€${selectedRangePrice.toFixed(2)})` : ""}`
673	                : "Sukurti žaidimą")}
