681	type FeedFilter = "all" | "booked" | "casual";
682	
683	export default function UnifiedMatchesPage() {
684	  const { user } = useUser();
685	  const [feedFilter, setFeedFilter] = useState<FeedFilter>("all");
686	  const [sport, setSport] = useState("all");
687	  const [selectedCities, setSelectedCities] = useState<string[]>([]);
688	  const [dateFilter, setDateFilter] = useState("");
689	  const [createOpen, setCreateOpen] = useState(false);
690	
691	  const { data, isLoading } = useQuery<{ matches: FeedItem[]; total: number }>({
692	    queryKey: ["open-matches", sport, dateFilter],
693	    queryFn: async () => {
694	      const params = new URLSearchParams();
695	      if (sport && sport !== "all") params.set("sport", sport);
696	      if (dateFilter) params.set("date", dateFilter);
697	      const r = await fetch(`${API}/matches/open?${params.toString()}`);
698	      if (!r.ok) throw new Error("Nepavyko gauti mačų");
699	      return r.json();
700	    },
701	  });
702	
703	  const allItems = data?.matches ?? [];
704	
705	  // Derive available cities from the loaded data
706	  const cityOptions = useMemo(() => {
707	    const seen = new Set<string>();
708	    for (const m of allItems) {
709	      const c = m.facilityCity || m.city;
710	      if (c) seen.add(c);
711	    }
712	    return Array.from(seen).sort();
713	  }, [allItems]);
714	
715	  const filtered = useMemo(() => {
716	    let items = allItems;
717	    if (feedFilter !== "all") items = items.filter(m => m.kind === feedFilter);
718	    if (selectedCities.length > 0) {
719	      items = items.filter(m => {
720	        const c = m.facilityCity || m.city;
721	        return c != null && selectedCities.includes(c);
722	      });
723	    }
724	    return items;
725	  }, [allItems, feedFilter, selectedCities]);
726	
727	  const bookedCount = allItems.filter(m => m.kind === "booked").length;
728	  const casualCount = allItems.filter(m => m.kind === "casual").length;
729	
730	  const TAB_CLS = (active: boolean) =>
731	    `px-4 py-2 rounded-full text-sm font-semibold transition-all border ${
732	      active
733	        ? "bg-primary text-primary-foreground border-primary"
734	        : "bg-transparent text-muted-foreground border-border hover:border-primary/40 hover:text-foreground"
735	    }`;
736	
737	  return (
738	    <Layout>
739	      <div className="min-h-screen bg-background">
740	        {/* Hero */}
741	        <div className="relative h-48 sm:h-60 overflow-hidden">
742	          <img
743	            src="/coaches/coach_banner_2.webp"
744	            srcSet="/coaches/coach_banner_2-480.webp 480w, /coaches/coach_banner_2-800.webp 800w, /coaches/coach_banner_2.webp 1200w"
745	            sizes="100vw"
746	            alt="Mačai"
747	            loading="eager"
748	            fetchPriority="high"
749	            decoding="async"
750	            width={1200}
751	            height={655}
752	            className="absolute inset-0 w-full h-full object-cover object-center"
753	          />
754	          <div className="absolute inset-0" style={{ background: "linear-gradient(to bottom, rgba(19,45,76,0.4), rgba(19,45,76,0.3), rgba(19,45,76,0.85))" }} />
755	          <div className="absolute inset-0 flex flex-col justify-end px-4 sm:px-8 pb-6 max-w-6xl mx-auto">
756	            <div className="flex items-center gap-2.5 mb-2">
757	              <div className="w-9 h-9 rounded-xl bg-primary/20 backdrop-blur-sm border border-primary/30 flex items-center justify-center">
758	                <Globe className="w-4 h-4 text-primary" />
759	              </div>
760	              <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-white drop-shadow">Mačai</h1>
761	            </div>
762	            <p className="text-white/80 text-sm max-w-xl drop-shadow-sm">
763	              Prisijunk prie atvirų mačų su kortu arba rask bendruomenės žaidimą. Sukurk savo ir pakvieskite žaidėjus.
764	            </p>
765	            <div className="mt-3 flex gap-2 flex-wrap">
766	              <Show when="signed-in">
767	                <Button size="sm" onClick={() => setCreateOpen(true)}
768	                  className="bg-primary text-primary-foreground hover:bg-primary/90 font-bold border-0">
769	                  <Plus className="w-3.5 h-3.5 mr-1.5" />Sukurti žaidimą
770	                </Button>
771	                <Button size="sm" asChild className="backdrop-blur-sm bg-white/15 hover:bg-white/25 text-white border border-white/30 font-semibold">
772	                  <Link href="/matches/mine">
773	                    <History className="w-3.5 h-3.5 mr-1.5" />Mano mačai
774	                  </Link>
775	                </Button>
776	              </Show>
777	              <Show when="signed-out">
778	                <Button size="sm" asChild className="backdrop-blur-sm bg-white/20 hover:bg-white/30 text-white border border-white/30">
779	                  <Link href="/sign-in">Prisijungti, kad sukurtum</Link>
780	                </Button>
781	              </Show>
782	            </div>
783	          </div>
784	        </div>
785	
786	        <div className="max-w-6xl mx-auto px-4 py-6 space-y-5">
787	          {/* Feed type tabs */}
788	          <div className="flex items-center gap-2 flex-wrap">
789	            <button className={TAB_CLS(feedFilter === "all")} onClick={() => setFeedFilter("all")}>
790	              Visi {allItems.length > 0 && <span className="ml-1 opacity-60 text-xs">({allItems.length})</span>}
791	            </button>
792	            <button className={TAB_CLS(feedFilter === "booked")} onClick={() => setFeedFilter("booked")}>
793	              <Zap className="w-3.5 h-3.5 inline mr-1" />
794	              Su kortu {bookedCount > 0 && <span className="ml-1 opacity-60 text-xs">({bookedCount})</span>}
795	            </button>
796	            <button className={TAB_CLS(feedFilter === "casual")} onClick={() => setFeedFilter("casual")}>
797	              <UserCheck className="w-3.5 h-3.5 inline mr-1" />
798	              Ieško kompanijos {casualCount > 0 && <span className="ml-1 opacity-60 text-xs">({casualCount})</span>}
799	            </button>
800	          </div>
801	
802	          {/* Filters */}
803	          <div className="bg-card border rounded-2xl p-4 space-y-3">
804	            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
805	              <Select value={sport} onValueChange={setSport}>
806	                <SelectTrigger className="h-9 text-sm">
807	                  <SelectValue placeholder="Visos sporto šakos" />
808	                </SelectTrigger>
809	                <SelectContent>
810	                  <SelectItem value="all">Visos sporto šakos</SelectItem>
811	                  {SPORTS.map(s => <SelectItem key={s} value={s}>{(SPORT_LABELS as any)[s] ?? s}</SelectItem>)}
812	                </SelectContent>
813	              </Select>
814	
815	              <CityMultiSelect options={cityOptions} selected={selectedCities} onChange={setSelectedCities} />
816	
817	              <Input type="date" value={dateFilter} onChange={e => setDateFilter(e.target.value)} className="h-9 text-sm" />
818	            </div>
819	
820	            {(sport !== "all" || selectedCities.length > 0 || dateFilter) && (
821	              <div className="flex justify-end border-t pt-2">
822	                <button onClick={() => { setSport("all"); setSelectedCities([]); setDateFilter(""); }}
823	                  className="text-xs text-muted-foreground hover:text-destructive transition-colors">
824	                  Išvalyti filtrus
825	                </button>
826	              </div>
827	            )}
828	          </div>
829	
830	          {/* Results */}
831	          {isLoading ? (
832	            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
833	              {Array.from({ length: 6 }).map((_, i) => <Skeleton key={i} className="h-72 rounded-2xl" />)}
834	            </div>
835	          ) : filtered.length === 0 ? (
836	            <div className="flex flex-col items-center justify-center py-20 text-center gap-4">
837	              <Globe className="w-12 h-12 text-muted-foreground/30" />
838	              <div>
839	                <p className="text-lg font-semibold text-muted-foreground">Nėra mačų</p>
840	                <p className="text-sm text-muted-foreground mt-1">
841	                  Pabandykite pakeisti filtrus arba sukurkite savo žaidimą.
842	                </p>
843	              </div>
844	              <div className="flex gap-2">
845	                <Show when="signed-in">
846	                  <Button onClick={() => setCreateOpen(true)} className="gap-1.5">
847	                    <Plus className="w-4 h-4" />Sukurti žaidimą
848	                  </Button>
849	                </Show>
850	                <Button variant="outline" asChild>
851	                  <Link href="/courts">Rasti aikštelę</Link>
852	                </Button>
853	              </div>
854	            </div>
855	          ) : (
856	            <>
857	              <p className="text-sm text-muted-foreground">
858	                Rodoma: <span className="font-semibold text-foreground">{filtered.length}</span> mačų
859	              </p>
860	              <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
861	                {filtered.map(m => (
862	                  <MatchCard key={`${m.kind}-${m.gameId}`} m={m} isOwn={!!user && m.creatorUserId === user.id} />
863	                ))}
864	              </div>
865	            </>
866	          )}
867	        </div>
868	      </div>
869	
870	      {user && <CreateGameDialog open={createOpen} onOpenChange={setCreateOpen} />}
871	    </Layout>
872	  );
873	}
