30	    // ── 1. Booked matches (split-payment games linked to a real court booking) ──
31	    const bookedConditions: any[] = [
32	      eq(gamesTable.visibility, "public"),
33	      eq(gamesTable.status, "awaiting_players"),
34	      gte(bookingsTable.date, today),
35	    ];
