44	        facility: facilitiesTable,
45	      })
46	      .from(gamesTable)
47	      .innerJoin(bookingsTable, eq(gamesTable.bookingId, bookingsTable.id))
48	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
49	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
50	      .where(and(...bookedConditions))
51	      .orderBy(bookingsTable.date, bookingsTable.startTime)
52	      .limit(maxRows);
53	
54	    // ── 2. Casual community games (no court booking) ──
55	    // isPrivate is the authoritative privacy field; visibility may be stale on older rows.
56	    const casualConditions: any[] = [
57	      eq(gamesTable.status, "open"),
58	      eq(gamesTable.isPrivate, false),
59	      isNull(gamesTable.bookingId),
60	      gte(gamesTable.datetime, nowIso),
61	    ];
62	    if (sport && sport !== "all") casualConditions.push(eq(gamesTable.sport, sport));
63	    if (city) casualConditions.push(eq(gamesTable.city, city));
64	
65	    const casualRows = await db
