78	    }
79	
80	    // ── 4. Apply optional skill filter to booked matches ──
81	    if (userSkill != null && !isNaN(userSkill)) {
82	      filteredBooked = filteredBooked.filter(r => {
83	        const min = r.game.minSkillLevel;
84	        const max = r.game.maxSkillLevel;
85	        if (min != null && userSkill < min) return false;
86	        if (max != null && userSkill > max) return false;
87	        return true;
88	      });
89	    }
90	
91	    // ── 5. Fetch creator ELO ratings per sport ──
92	    const creatorSportPairs = [
93	      ...filteredBooked.map(r => ({ userId: r.game.creatorUserId, sport: r.game.sport })),
94	      ...filteredCasual.map(r => ({ userId: r.game.creatorUserId, sport: r.game.sport })),
95	    ];
96	    const uniqueCreatorIds = [...new Set(creatorSportPairs.map(p => p.userId))];
97	    const creatorEloMap = new Map<string, number>(); // key: "userId::sport"
98	    if (uniqueCreatorIds.length > 0) {
99	      const ratingRows = await db
100	        .select({ userId: userRatingsTable.userId, sportSlug: userRatingsTable.sportSlug, elo: userRatingsTable.elo })
101	        .from(userRatingsTable)
