104	    }
105	
106	    // ── 7. Aggregate participant counts for all games ──
107	    const allGameIds = [
108	      ...filteredBooked.map(r => r.game.id),
109	      ...filteredCasual.map(r => r.game.id),
110	    ];
111	    const participantCounts = new Map<number, { paid: number; pending: number; joined: number }>();
112	
113	    if (allGameIds.length > 0) {
114	      const participantRows = await db
115	        .select({
116	          gameId: gameParticipantsTable.gameId,
117	          paymentStatus: gameParticipantsTable.paymentStatus,
118	          count: sql<string>`count(*)`,
119	        })
120	        .from(gameParticipantsTable)
121	        .where(and(
122	          eq(gameParticipantsTable.status, "joined"),
123	          inArray(gameParticipantsTable.gameId, allGameIds),
124	        ))
125	        .groupBy(gameParticipantsTable.gameId, gameParticipantsTable.paymentStatus);
126	
127	      for (const row of participantRows) {
128	        const existing = participantCounts.get(row.gameId) ?? { paid: 0, pending: 0, joined: 0 };
129	        const c = parseInt(row.count, 10);
130	        if (row.paymentStatus === "paid") existing.paid += c;
131	        else existing.pending += c;
132	        existing.joined += c;
133	        participantCounts.set(row.gameId, existing);
134	      }
135	    }
136	
137	    // ── 8. Build booked match items ──
138	    const bookedItems = filteredBooked.map(r => {
139	      const { game, booking, court, facility } = r;
