144	      return {
145	        kind: "booked" as const,
146	        gameId: game.id,
147	        sport: game.sport,
148	        matchType: game.matchType,
149	        visibility: game.visibility,
150	        creatorName: game.creatorName,
151	        creatorUserId: game.creatorUserId,
152	        description: game.description ?? null,
153	        datetime,
154	        minSkillLevel: game.minSkillLevel ?? null,
155	        maxSkillLevel: game.maxSkillLevel ?? null,
156	        // Booked-only
157	        bookingId: booking.id,
158	        token: booking.splitInviteToken ?? null,
159	        courtName: court?.name ?? "",
160	        courtId: court?.id ?? null,
161	        facilityName: facility?.name ?? "",
162	        facilityCity: facility?.city ?? "",
163	        courtImageUrl: court?.imageUrl ?? null,
164	        date: booking.date,
165	        startTime: booking.startTime,
166	        endTime: booking.endTime,
167	        pricePerSlot: Number(booking.pricePerSlot ?? 0),
168	        totalPrice: Number(booking.totalPrice),
169	        totalSlots: total,
170	        paidSlots: counts.paid,
171	        slotsLeft,
172	        // Casual-only (null for booked)
173	        city: facility?.city ?? null,
174	        placeName: null as string | null,
175	        skillLevel: null as string | null,
176	        durationMinutes: null as number | null,
177	        joinedCount: null as number | null,
178	        playersNeeded: null as number | null,
179	        isPrivate: false,
180	        creatorElo: creatorEloMap.get(`${game.creatorUserId}::${game.sport}`) ?? null,
181	        createdAt: game.createdAt.toISOString(),
182	      };
183	    });
184	
185	    // ── 9. Build casual game items ──
186	    const casualItems = filteredCasual.map(r => {
187	      const { game } = r;
188	      const counts = participantCounts.get(game.id) ?? { paid: 0, pending: 0, joined: 0 };
189	      const slotsLeft = Math.max(0, (game.playersNeeded ?? 2) - counts.joined);
190	      return {
191	        kind: "casual" as const,
192	        gameId: game.id,
193	        sport: game.sport,
194	        matchType: game.matchType,
195	        visibility: game.visibility,
196	        creatorName: game.creatorName,
197	        creatorUserId: game.creatorUserId,
198	        description: game.description ?? null,
199	        datetime: String(game.datetime),
200	        minSkillLevel: null as number | null,
201	        maxSkillLevel: null as number | null,
202	        // Booked-only (null for casual)
203	        bookingId: null as number | null,
204	        token: null as string | null,
205	        courtName: null as string | null,
206	        courtId: null as number | null,
207	        facilityName: null as string | null,
208	        facilityCity: null as string | null,
209	        courtImageUrl: null as string | null,
210	        date: null as string | null,
211	        startTime: null as string | null,
212	        endTime: null as string | null,
213	        pricePerSlot: null as number | null,
214	        totalPrice: null as number | null,
215	        totalSlots: null as number | null,
216	        paidSlots: null as number | null,
217	        slotsLeft,
218	        // Casual-only
219	        city: game.city ?? null,
220	        placeName: game.placeName ?? null,
221	        skillLevel: game.skillLevel ?? null,
