227	        createdAt: game.createdAt.toISOString(),
228	      };
229	    });
230	
231	    // ── 10. Merge and sort by datetime ascending ──
232	    const allItems = [...bookedItems, ...casualItems].sort((a, b) =>
233	      new Date(a.datetime).getTime() - new Date(b.datetime).getTime(),
234	    );
235	
236	    res.json({ matches: allItems, total: allItems.length });
237	  } catch (err) {
238	    logger.error({ err }, "GET /api/matches/open failed");
239	    res.status(500).json({ error: "Nepavyko gauti mačų sąrašo" });
240	  }
241	});
